WITH valid_departments AS (SELECT *, CONCAT(dept_name, ' - ', location) AS dept_name_location FROM departments WHERE budget > 1810000 AND dept_name IS NOT NULL AND location IN ('Singapore', 'London')), DepartmentsStats AS (SELECT CASE WHEN budget >= 3194000 THEN 'high' WHEN budget >= 1473000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(CASE WHEN dept_name = 'Finance' THEN 1 ELSE 0 END) AS finance_count FROM valid_departments GROUP BY CASE WHEN budget >= 3194000 THEN 'high' WHEN budget >= 1473000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, finance_count FROM DepartmentsStats ORDER BY finance_count DESC
